import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"2007年 · 三类企业","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2007年.md","filePath":"05_quotes/by-year/2007年.md"}'),r={name:"05_quotes/by-year/2007年.md"};function u(q,e,s,c,h,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2007年-·-三类企业" tabindex="-1">2007年 · 三类企业 <a class="header-anchor" href="#_2007年-·-三类企业" aria-label="Permalink to &quot;2007年 · 三类企业&quot;">​</a></h1><blockquote><p>真正伟大的企业必须有持久的&quot;护城河&quot;，保护投入资本获得高额回报。资本主义动力学保证，竞争对手会不断攻击任何赚取高回报的企业&quot;城堡&quot;。——巴菲特（77岁）</p></blockquote><p>本页收录2007年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>退潮才知道谁在裸泳——我们现在在一些最大金融机构看到的，真是不堪入目。</p></blockquote><blockquote><p>最糟糕的企业就是那种增长很快，需要大量资本才能实现增长，然后赚不到什么钱。想想航空公司。</p></blockquote><blockquote><p>必须不断重建的护城河，最终根本就不是护城河。</p></blockquote><blockquote><p>强大的壁垒，比如成为低成本生产商，或者拥有全球强大品牌，对持续成功至关重要。</p></blockquote><blockquote><p>拥有希望钻石一部分，好过拥有整颗莱茵石。</p></blockquote><blockquote><p>好账户：给你非常高的利率，随着年份增长利率还会上升。不错账户：给你有吸引力的利率，你增加存款也能赚利息。糟糕账户：给你不足的利率，还要求你不断加钱，才能拿到那些令人失望的回报。</p></blockquote><blockquote><p>如果一个企业需要超级明星才能产生伟大结果，它本身不能被认为是伟大企业。</p></blockquote><blockquote><p>我从来没和丑女人睡过，但我醒过来身边不少。</p></blockquote><blockquote><p>我们评估进步的两个方法：第一个就是测试盈利增长；第二个更主观，就是测试它的&quot;护城河&quot;——过去一年有没有变宽。</p></blockquote><blockquote><p>我该行动时却只是空谈。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2007年伯克希尔每股账面价值增长11%。巴菲特以45亿美元收购Marmon集团60%股权，完成与普利兹克家族&quot;一言既出驷马难追&quot;的交易。本年他系统阐述&quot;好企业、不错企业、糟糕企业&quot;分类框架，以喜诗糖果、飞安国际和航空业为经典案例，深刻反思自己在Dexter鞋业上用股票支付的220亿美元错误。随着次贷危机苗头初现，他警告&quot;退潮才知道谁在裸泳&quot;。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2007年-翻译-·-01-letters-2007年-核心总结-·-01-letters-2007年-思维导图" tabindex="-1"><a href="/01_letters/2007年/翻译.html">01_letters/2007年/翻译</a> · <a href="/01_letters/2007年/核心总结.html">01_letters/2007年/核心总结</a> · <a href="/01_letters/2007年/思维导图.html">01_letters/2007年/思维导图</a> <a class="header-anchor" href="#_01-letters-2007年-翻译-·-01-letters-2007年-核心总结-·-01-letters-2007年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2007年/翻译]] · [[→ 核心总结|01_letters/2007年/核心总结]] · [[→ 思维导图|01_letters/2007年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2007年/翻译.html">/01_letters/2007年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",u]]);export{i as __pageData,p as default};
